import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    // Pattern allows alphanumeric, spaces, hyphens, and common punctuation
    private static final Pattern DISPLAY_SANITIZER = Pattern.compile("[<>]");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String reportType = request.getParameter("type");
        String startDate = request.getParameter("start");
        String endDate = request.getParameter("end");
        String department = request.getParameter("dept");

        if (reportType == null || startDate == null || endDate == null) {
            response.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            response.sendError(400, "Invalid date format");
            return;
        }

        // Sanitize department for display purposes (XSS prevention)
        String safeDept = department != null ? DISPLAY_SANITIZER.matcher(department).replaceAll("") : "all";

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();
            stmt = conn.createStatement();

            // Build query based on report type
            String query;
            if ("summary".equals(reportType)) {
                query = "SELECT department, COUNT(*) as cnt, SUM(amount) as total " +
                        "FROM transactions WHERE tx_date BETWEEN '" + startDate + "' AND '" + endDate + "'";
            } else if ("detail".equals(reportType)) {
                query = "SELECT * FROM transactions WHERE tx_date BETWEEN '" + startDate + "' AND '" + endDate + "'";
            } else {
                response.sendError(400, "Invalid report type");
                return;
            }

            // Apply department filter if specified
            if (department != null && !department.isEmpty()) {
                query += " AND department = '" + department + "'";
            }

            if ("summary".equals(reportType)) {
                query += " GROUP BY department ORDER BY total DESC";
            }

            log.info("Executing report query for type=" + reportType);
            rs = stmt.executeQuery(query);

            response.setContentType("text/html; charset=UTF-8");
            PrintWriter out = response.getWriter();
            out.println("<html><head><title>Report: " + safeDept + "</title></head><body>");
            out.println("<h1>Transaction Report</h1>");
            out.println("<p>Department: " + safeDept + " | Period: " + startDate + " to " + endDate + "</p>");
            out.println("<table border='1'><tr>");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + meta.getColumnName(i) + "</th>");
            }
            out.println("</tr>");

            while (rs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + rs.getString(i) + "</td>");
                }
                out.println("</tr>");
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            response.sendError(500, "Report generation failed");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private Connection getConnection() throws SQLException {
        // Connection pool managed by container
        try {
            Class.forName("org.postgresql.Driver");
        } catch (ClassNotFoundException e) {
            throw new SQLException("Driver not found");
        }
        String url = System.getenv("DB_URL");
        String user = System.getenv("DB_USER");
        String pass = System.getenv("DB_PASS");
        return DriverManager.getConnection(url, user, pass);
    }
}
